export function solveEvents(progress,catalog){const map=new Map(catalog.map(p=>[p.id,p]));return Object.entries(progress.solved||{}).filter(([id,at])=>map.has(id)&&Number.isFinite(at)&&at>0&&at<7258118400000).map(([id,at])=>({day:new Date(at).toISOString().slice(0,10),topic:map.get(id).topic}));}
export function bucketSolves(events,{mode='daily',month=new Date().toISOString().slice(0,7),year=new Date().getUTCFullYear(),topic=''}={}){year=Number(year);if(!Number.isInteger(year)||year<2000||year>2200||!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))throw new Error('Choose a valid date.');const keys=mode==='daily'?Array.from({length:new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5)),0)).getUTCDate()},(_,i)=>month+'-'+String(i+1).padStart(2,'0')):mode==='monthly'?Array.from({length:12},(_,i)=>year+'-'+String(i+1).padStart(2,'0')):Array.from({length:5},(_,i)=>String(year-4+i));const counts=new Map(keys.map(k=>[k,0])),topics=new Map();for(const e of events){if(!/^\d{4}-\d{2}-\d{2}$/.test(e.day)||new Date(e.day+'T00:00:00Z').toISOString().slice(0,10)!==e.day||topic&&e.topic!==topic)continue;const key=e.day.slice(0,mode==='daily'?10:mode==='monthly'?7:4);if(!counts.has(key))continue;counts.set(key,counts.get(key)+1);topics.set(e.topic,(topics.get(e.topic)||0)+1);}return{keys,values:keys.map(k=>counts.get(k)),topics:[...topics].sort((a,b)=>b[1]-a[1]),total:[...counts.values()].reduce((a,b)=>a+b,0)};}
